from hypothesis import example, given, settings
from hypothesis import strategies as st

from rle import decode, encode

# Shrunk counterexample found by Hypothesis against the ORIGINAL buggy codec:
#   Falsifying example: s='0000000000'
# Ten identical DIGIT characters hit both defects at once:
#   - encode produced '010' but decode read exactly ONE count digit ('1'),
#     dropped the trailing '0', and desynchronized (IndexError / corruption);
#   - any digit payload (e.g. 'a2b') was indistinguishable from a count,
#     so runs were misparsed even below length 10.
ascii_letters_text = st.text(alphabet=st.characters(min_codepoint=33, max_codepoint=126), min_size=1)


@settings(max_examples=300)
@given(st.text())
@example('aaaaaaaaaaab')   # run of 11: broke the single-digit-count decoder
@example('a2b')             # digit payload: confused with a run count
def test_roundtrip(s):
    assert decode(encode(s)) == s


@settings(max_examples=300)
@given(ascii_letters_text)
def test_encode_length_bound(s):
    assert len(encode(s)) <= 3 * len(s)


def test_explicit_run_over_nine():
    assert encode('aaaaaaaaaaab') == 'a11b1'
    assert decode('a11b') == 'aaaaaaaaaaab'


def test_explicit_digit_payload():
    assert encode('a2b') == 'a1\\21b1'
    assert decode('a2b') == 'a2b'
